import {COURSES,text} from './curriculum-model.js';
import {UNIT_SOURCES,lessonFor} from './lesson-content.js';
import {COVERAGE} from './teacher-coverage.js';
const lang=new URLSearchParams(location.search).get('lang')==='en'?'en':'ko',en=lang==='en',t=p=>text(p,lang),say=(ko,eng)=>en?eng:ko,$=id=>document.getElementById(id),el=(tag,parent,value)=>{const e=document.createElement(tag);if(value!==undefined)e.textContent=value;parent.append(e);return e;};document.documentElement.lang=lang;
$('lab').textContent=say('실험실','Laboratory');$('lab').href='index.html?lang='+lang;$('records').textContent=say('기록·학습 근거 검토','Review learning evidence');$('records').href='teacher.html?lang='+lang;
$('title').textContent=say('힘과 평형 · 교사 안내와 지도서 대조','Forces & equilibrium · teacher guide and coverage');
$('intro').textContent=say('같은 교실·실험대·수레에서 초등 11개, 중등 17개, 고등 물리학 7개 활동을 진행합니다. 역학과 에너지 2개는 별도의 교육과정 확장입니다. 37개 활동과 117개 안내 조건마다 예상, 조작, 관찰, 설명과 적용을 기록합니다.','The same room, bench and cart host 11 elementary, 17 middle-school and 7 Physics activities, plus 2 curriculum-based Mechanics extensions. Predictions, manipulation, observations, explanations and transfer are recorded across 37 activities and 117 guided conditions.');
$('scope').textContent=say('확인한 범위: 2022 개정 아이스크림 과학 3-1 지도서 힘 단원104–175쪽, 비상 과학1 지도서 힘 단원334–401쪽, 비상 고등 물리학 평형과 안정성80–86쪽. 학생의 핵심·탐구·평가·생활 적용을 원문 순서로 재구성했습니다. 교사용 배경과 선택 보충은 구분합니다. 자동 확인은 제출한 실험·응답의 근거를 뜻하며 실제 학습 습득이나 협력·경청을 인증하지 않습니다. 발표, 조사 출처, 동료 평가와 확장 설계는 교사가 검토합니다.','Verified scope: 2022 i-scream Science 3-1 teacher guide pp.104–175, Visang Science 1 pp.334–401, and high-school Physics equilibrium/stability pp.80–86. Core student content, investigations, assessment and transfer follow the source order. Teacher background and optional extensions are separate. Automated checks verify submitted evidence, not mastery, collaboration or listening. Teachers review presentations, sources, peer feedback and extension designs.');
el('h2',$('flow'),say('한 활동의 수업 순서','Sequence within an activity'));const flow=el('ol',$('flow'));for(const p of [['준비: 기구·안전·처음 예상을 확인합니다. 저울의 수평·전원·영점, 센서의 영점과 처음 위치는 학생이 직접 조작합니다.','Prepare: inspect apparatus, care and initial prediction. Learners operate level, power, zero and initial-mark actions.'],['실험: 현재 한 조건만 크게 안내합니다. 안내 행과 자유 탐구를 구분하고, 실제 측정 후에만 기록합니다. 지레의 빈칸은 추를 조작해 찾습니다.','Test: one current instruction. Guided evidence and free exploration are separate. Record only after measurement; discover lever blanks by manipulation.'],['정리: 바뀐 조건과 결과를 비교합니다. 용수철 그래프는 같은 용수철에서 학생이 실제 측정한 점만 표시합니다. 오답은 관련 실험으로 돌아가 재검토합니다.','Explain: compare highlighted changed conditions and results. Spring graphs show measured points from one spring only. Revisit relevant experiments after incorrect responses.'],['적용: 새 상황을 설명하고 처음 예상과 비교합니다. 설계·수정 전후·발표·동료 의견·선택 확장 결과를 저장합니다.','Apply: explain a new case and compare with the initial prediction. Save plans, revisions, presentations, feedback and optional extensions.']])el('li',flow,t(p));
el('p',$('flow'),say('과정을 통째로 한 수업에 끝내지 않습니다. 초등 원단원12차시와 중등 차시 구성을 기준으로 선택한 활동을 나누고, 실제 기구 실험·모둠 발표와 연결하세요.','Do not attempt a complete route in one lesson. Split activities using the elementary 12-lesson unit and middle-school lesson structure, with physical apparatus and group presentation.'));
el('h2',$('flow'),say('장면에서 직접 조작하기','Manipulate the scene'));el('p',$('flow'),say('점선 원과 화살표가 현재 잡을 곳과 움직일 방향을 가리킵니다. 수레를 밀고 놓기, 추를 판에 올리거나 칸 사이로 옮기기, 용수철 끝 당기기, 매단 추 물속으로 내리기, 지레 누르기와 빗면 끌기를 장면에서 수행합니다. 저울은 물체를 끌어 놓고 눈금을 직접 읽습니다. 영점·수평·전원은 기구의 표시를 눌러 준비합니다.','Dashed rings and arrows mark where to grab and move. Push and release the cart, place or slide beam loads, pull the spring end, lower suspended weights, press the lever and pull up the ramp. Drag samples onto scales and read the instrument yourself. Instrument markers operate zero, level and power.'));el('p',$('flow'),say('키보드: 표시로 이동한 뒤 Space 또는 Enter로 잡고 방향키로 움직입니다. Enter로 놓고 Esc로 취소합니다. 숫자·버튼으로 조작을 펼치면 기존 입력도 사용할 수 있습니다. 잘못 놓기·취소·짧은 들어 올리기에는 측정 기록이 생기지 않습니다.','Keyboard: focus a marker, grab with Space or Enter, move with arrows, release with Enter, or cancel with Esc. Expand Use values and buttons for alternative controls. Invalid drops, cancellation and incomplete lifts make no measurement record.'));el('p',$('models'),say('드래그 거리는 입력을 선택하는 화면 축척이며 학생의 실제 손힘이나 일의 측정값이 아닙니다. 수레의 화살표 길이로 선택한 힘을 확인하고 놓은 뒤 같은1.2초를 관찰합니다. 직접 들어 올리기는 위쪽 표시선까지 이동한 경우에만 기록합니다.','Dragging distance selects an interface input; it is not a measurement of the learner’s physical hand force or work. Read the chosen cart force from the arrow, release, then observe the same1.2 seconds. A manual lift is recorded only after reaching the upper guide.'));
for(const [id,c]of Object.entries(COURSES)){el('h2',$('courses'),t(c.label));const link=el('a',$('courses'),say('이 과정 열기','Open this course'));link.href='index.html?course='+id+'&lang='+lang;for(const [i,a]of c.activities.entries()){const l=lessonFor(id,a.id),d=el('details',$('courses'));el('summary',d,(i+1)+'. '+t(a.title)+' · '+a.codes.join(', '));el('p',d,say('지도서/근거 쪽: ','Source pages: ')+l.pages+' · '+UNIT_SOURCES.find(s=>s.id===l.source).title);el('p',d,t(l.kit));const steps=el('ol',d);for(const f of l.frames)el('li',steps,t(f.title));el('p',d,say('설명 질문: ','Evidence question: ')+t(a.prompt));el('p',d,say('안전: ','Care: ')+t(l.safety));for(const x of l.extensions||[])el('p',d,say('선택 확장: ','Optional extension: ')+t(x.title)+' — '+t(x.task));}}
el('h2',$('models'),say('학생 화면과 교사 배경의 구분','Student content and teacher background'));const list=el('ul',$('models'));for(const p of [
 ['초등에는 힘 정의·질량 구분·돌림힘 공식·후크 법칙·일 계산을 요구하지 않습니다. 수평대는 같은 거리와 다른 거리의 관찰을 구별하고, 도구는 같은 짐의 직접 들기와 각각 비교합니다. 지레와 빗면의 우열을 일반화하지 않습니다.','Elementary learners are not assessed on formal force, mass distinction, torque, Hooke’s law or work. Distinguish equal/unequal distances and compare each tool with direct lifting, without universally ranking tools.'],
 ['중등은 힘의 세 요소·나란한 합력·중력·탄성력·마찰력·부력·운동 변화·생활 설계를 다룹니다. 마찰계수나 훅의 식은 교사 배경에만 둡니다. 바닥 지지힘과 생활 적용은9과05-04에 연결합니다.','Middle school covers force features, parallel resultants, gravity, elasticity, friction, buoyancy, motion and design. Coefficients and Hooke’s formula remain teacher background. Support and daily application map to9과05-04.'],
 ['수레는 마찰 없는 수평면에서1.2초를 비교합니다. 관찰 종료는 시간 정지이며 힘 때문에 멈춘 것이 아닙니다. 컬링의 스톤/상자를 기존 수레로 바꾼 재구성입니다.','The cart uses a frictionless plane with a1.2s observation. Observation freeze is not a physical stop. The existing cart substitutes for curling stones and boxes.'],
 ['마찰 기구는 정지한 나무도막의 시작 힘을 천천히 증가시켜 비교합니다. 내부식은F시작=μmg입니다. 이 μ는 시각화용 이상값이며 실측 결과를 보장하지 않습니다.','Friction uses a resting block and increasing pulling force. Internal onset model isF=μmg; chosen ideal values are not real measurements.'],
 ['용수철은F=kΔx, 늘어난 길이5–25cm를 사용합니다. 기본k=50N/m, 비교용100N/m. 눈금과 끝점은 같은 축척이며 그래프는 동일 용수철만 비교합니다. 초등 용수철저울은250g 범위·큰25g·작은5g 눈금입니다.','Spring force usesF=kΔx, extension5–25cm andk=50 or100N/m. Ruler and endpoint agree; graphs separate spring types. Elementary scale capacity is250g with25g/5g divisions.'],
 ['부력은ρgV, 센서 장력은mg−ρgV입니다. 매단 추의 질량은1kg, 각 추 부피200cm³, 물 밀도1000kg/m³입니다. 잠수부는부피, 풍선은클립질량, 잠수함은탱크물질량을 바꿉니다. 풍선은5L, 공기1.2·헬륨0.18kg/m³, 껍질2.1g·클립1g이므로3개에서 평형입니다. 물속 움직임은 방향을 보여 주는 도식이며 유체 항력·속도는 계산하지 않습니다.','Buoyancy isρgV and suspension tensionmg−ρgV. Suspended mass1kg, each weight volume200cm³, water density1000kg/m³. Diver volume, balloon payload and submarine ballast are distinct. The5L balloon uses air1.2/helium0.18kg/m³, shell2.1g and1g clips, balancing with3clips. Fluid motion is a directional illustration, without drag/velocity integration.'],
 ['고등은ΣF=0과Στ=0을 함께 확인합니다. 돌림힘τ=rFsinθ, 반시계방향을양으로 둡니다. 어긋난두힘의작용선간거리는1m입니다. 선반은질량없는3m판·2m지점120N으로받침40N,줄80N. 구조물은받침모서리기준으로무게중심수직선을계산하며 복원·넘어짐애니메이션은각도시간측정이아닙니다.','High school checksΣF=0 andΣτ=0, usingτ=rFsinθ with anticlockwise positive. Couple separation is1m. A massless3m shelf with120N at2m gives40N support and80N tension. Stability uses the centre projection about the support edge; release animations are not angular time-series measurements.'],
 ['설계 시험의 마찰 제동거리v²/(2μg), 완충재 최대 압축√(mv²/k)와접근거리0.3m를사용합니다. 최대압축시점까지만비교하고이후복원은생략합니다. 보조로봇은사람힘30%라는정성예시로 실제제품효율을뜻하지않습니다.','Design uses braking distancev²/(2μg) and bumper maximum compression√(mv²/k), after0.3m approach. Compare through maximum compression; later rebound is omitted. Assisted lifting uses an illustrative30% human effort, not a product efficiency.'],
 ['개인정보·서버 자동 전송 없이 브라우저에 저장합니다. JSON 파일에 예상·첫답/수정답·조건·측정·설명·설계·동료 의견을 포함합니다. v3 기록은 보존하며 새 안내 실험을 완료했다고 소급하지 않습니다.','Records stay in the browser without personal identifiers or automatic server upload. JSON includes predictions, answer attempts, conditions, measurements, explanations, designs and feedback. Older records are preserved without inventing new guided completion.']])el('li',list,t(p));
el('h2',$('sources'),say('원문과 목표별 구현 대조','Original sources and objective coverage'));for(const source of UNIT_SOURCES){const p=el('p',$('sources')),a=el('a',p,source.title);a.href=source.url;a.target='_blank';a.rel='noopener';el('small',p,' · '+source.pages+' · '+t(source.scope));}for(const [cid,goals]of Object.entries(COVERAGE)){const d=el('details',$('sources'));el('summary',d,t(COURSES[cid].label)+' · '+goals.length+say('개 확인 항목',' coverage items'));const scroll=el('div',d);scroll.className='scroll';const table=el('table',scroll);const head=el('tr',el('thead',table));for(const title of [say('항목·쪽수','Item/pages'),say('학생 목표','Student objective'),say('연결 활동·검토','Activities/review')])el('th',head,title);const body=el('tbody',table);for(const goal of goals){const row=el('tr',body);el('td',row,goal.id+' · '+goal.pages);el('td',row,t(goal.title));el('td',row,goal.activities.map(id=>t(COURSES[cid].activities.find(a=>a.id===id).title)).join(' / ')+(goal.manual?say(' · 교사 검토 포함',' · includes teacher review'):''));}}
el('p',$('models'),say('추 개수 실험의 수치 모형은 추 1개 100 g, 한 칸 0.1 m입니다. 수평 조건은 개수와 칸의 곱으로 비교하며 기구는 확대해서 그립니다.','The count-based lever model uses 100 g per weight and 0.1 m per division. Compare count × division for balance; the apparatus is enlarged.'));

const auditLink=el('a',$('sources'),say('2026-10-17 학생 경로 검수·수정 내역','Student-journey audit and repairs, 2026-10-17'));auditLink.href='docs/teaching-audit-2026-10-17.md';
el('p',$('models'),say('직접 들기·지레·빗면은 같은 추의 0.5 m 상승을 비교합니다. 초등의 힘 비교 눈금은 직접 들기 100칸을 기준으로 하며 N 단위 측정이 아닙니다. 모빌은 구슬·별·마름모를 선택하고 무게와 위치를 수정합니다. 오른쪽 장식 개수는 같은 총무게를 나누는 수입니다.','Direct, lever and ramp methods compare the same load rising 0.5 m. Elementary effort uses 100 relative units for direct lifting, rather than a reading in N. Mobile builders select beads, stars or diamonds and revise load and position; right-hand count divides the same total load.'));
